import{_ as r,o as t,c as a,ae as e}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"产品发布 - 2026-06-10","description":"","frontmatter":{"date":"2026-06-10T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-06-10-product.md","filePath":"daily/2026-06-10-product.md"}'),n={name:"daily/2026-06-10-product.md"};function i(s,o,g,p,l,h){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="产品发布-2026-06-10" tabindex="-1">产品发布 - 2026-06-10 <a class="header-anchor" href="#产品发布-2026-06-10" aria-label="Permalink to &quot;产品发布 - 2026-06-10&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日AI产品领域主要动态包括Notion AI功能更新、微软Copilot聊天助手发布、digital.ai数字工作流概览发布、Figma AI原型工具开放以及产品副驾驶AI助手集成。最值得关注的是微软Copilot聊天助手的发布，它基于大型语言模型，预示着AI在聊天助手领域的新突破；同时，Figma的AI原型工具Figma Make向所有用户开放，将极大提升设计师和开发者的工作效率。</p><hr><h3 id="_1-notion-ai功能更新与新特性" tabindex="-1">1. Notion AI功能更新与新特性 <a class="header-anchor" href="#_1-notion-ai功能更新与新特性" aria-label="Permalink to &quot;1. Notion AI功能更新与新特性&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features - Matthias Frank</a></p><p><strong>一句话摘要</strong>: Notion AI新增日历集成、图像生成限制提升等功能。</p><p><strong>能解决什么问题</strong>: 提高工作效率，简化日程安排和视觉内容创作。</p><p><strong>产品应用</strong>: 适用于需要日程管理、视觉设计和知识搜索的产品。</p><p><strong>示例场景</strong>: 自动安排团队会议并生成会议邀请。</p><hr><h3 id="_2-微软copilot-维基百科" tabindex="-1">2. 微软Copilot - 维基百科 <a class="header-anchor" href="#_2-微软copilot-维基百科" aria-label="Permalink to &quot;2. 微软Copilot - 维基百科&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot - Wikipedia</a></p><p><strong>一句话摘要</strong>: 微软基于大型语言模型开发的人工智能聊天助手。</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供更智能的虚拟助手服务。</p><p><strong>产品应用</strong>: 可应用于Windows、Microsoft 365等，提升工作效率。</p><p><strong>示例场景</strong>: 通过Copilot Studio创建定制化的AI助手。</p><hr><h3 id="_3-数字工作流概览-·-digital-ai-发布" tabindex="-1">3. 数字工作流概览 · digital.ai 发布 <a class="header-anchor" href="#_3-数字工作流概览-·-digital-ai-发布" aria-label="Permalink to &quot;3. 数字工作流概览 · digital.ai 发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: digital.ai 发布新自助工作流简化应用上线流程。</p><p><strong>能解决什么问题</strong>: 帮助开发者在对工具了解有限的情况下轻松上线应用。</p><p><strong>产品应用</strong>: 适用于需要自动化部署和优化云应用性能的企业。</p><p><strong>示例场景</strong>: 云应用性能优化和安全性合规性自动化。</p><hr><h3 id="_4-figma发布面向设计师和开发者的ai原型工具" tabindex="-1">4. Figma发布面向设计师和开发者的AI原型工具 <a class="header-anchor" href="#_4-figma发布面向设计师和开发者的ai原型工具" aria-label="Permalink to &quot;4. Figma发布面向设计师和开发者的AI原型工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.cmswire.com/digital-experience/figma-make-ai-prototyping-tool-exits-beta-for-all-users" target="_blank" rel="noreferrer">Figma Launches AI Prototyping Tools for Designers &amp; Developers</a></p><p><strong>一句话摘要</strong>: Figma的AI原型工具Figma Make结束测试，向所有用户开放。</p><p><strong>能解决什么问题</strong>: 解决设计师和产品构建者无需技术背景即可创建交互式原型的问题。</p><p><strong>产品应用</strong>: 可应用于产品开发流程，通过AI工具加速设计到原型的转换。</p><p><strong>示例场景</strong>: 设计师利用Figma Make将静态设计快速转化为可交互原型。</p><hr><h3 id="_5-产品副驾驶——软件产品团队的ai助手" tabindex="-1">5. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_5-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;5. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: 产品副驾驶是集成在Jira和Confluence中的AI助手，帮助产品管理。</p><p><strong>能解决什么问题</strong>: 解决产品团队在创建清晰任务、回答问题、清理积压工作和保持文档更新中的效率问题。</p><p><strong>产品应用</strong>: 适用于需要优化产品管理流程的软件团队，直接在Jira和Confluence中使用。</p><p><strong>示例场景</strong>: 产品负责人使用产品副驾驶快速创建清晰任务和维护文档。</p><hr><h3 id="_6-figma产品新闻和发布说明" tabindex="-1">6. Figma产品新闻和发布说明 <a class="header-anchor" href="#_6-figma产品新闻和发布说明" aria-label="Permalink to &quot;6. Figma产品新闻和发布说明&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/release-notes" target="_blank" rel="noreferrer">Figma product news and release notes</a></p><p><strong>一句话摘要</strong>: Figma推出AI设计助手，增强原型制作和代码编辑功能。</p><p><strong>能解决什么问题</strong>: 解决设计自动化、代码编辑复杂和设计系统整合问题。</p><p><strong>产品应用</strong>: 适用于专业设计团队，提高设计效率和代码管理。</p><p><strong>示例场景</strong>: 设计师使用Figma AI助手自动生成设计草图。</p><hr><h3 id="_7-微软copilot-组织的ai工具" tabindex="-1">7. 微软Copilot | 组织的AI工具 <a class="header-anchor" href="#_7-微软copilot-组织的ai工具" aria-label="Permalink to &quot;7. 微软Copilot | 组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot系列AI工具助力组织提升效率和安全性。</p><p><strong>能解决什么问题</strong>: 提升组织的日常工作效率和安全性，同时保持合规性。</p><p><strong>产品应用</strong>: 可以应用于企业日常运营，如文档编辑、数据分析和代码编写。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot提高文档处理效率。</p><hr><h3 id="_8-notion文档更新日志" tabindex="-1">8. Notion文档更新日志 <a class="header-anchor" href="#_8-notion文档更新日志" aria-label="Permalink to &quot;8. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion API新增Markdown内容API和AI会议记录查询功能</p><p><strong>能解决什么问题</strong>: 提高内容创建和会议记录管理的效率</p><p><strong>产品应用</strong>: 适用于需要高效内容管理和会议记录自动化的产品</p><p><strong>示例场景</strong>: 使用Notion API自动生成会议记录摘要</p><hr><h3 id="_9-在figma设计中使用ai工具" tabindex="-1">9. 在Figma设计中使用AI工具 <a class="header-anchor" href="#_9-在figma设计中使用ai工具" aria-label="Permalink to &quot;9. 在Figma设计中使用AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://help.figma.com/hc/en-us/articles/23870272542231-Use-AI-tools-in-Figma-Design" target="_blank" rel="noreferrer">Use AI tools in Figma Design</a></p><p><strong>一句话摘要</strong>: 探索Figma设计中所有可用的AI功能。</p><p><strong>能解决什么问题</strong>: 提高设计效率，快速找到所需资源并保持工作流程。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI加速设计流程和资源查找。</p><p><strong>示例场景</strong>: 设计师使用First Draft功能快速迭代设计草图。</p><hr><h3 id="_10-figma-维基百科" tabindex="-1">10. Figma - 维基百科 <a class="header-anchor" href="#_10-figma-维基百科" aria-label="Permalink to &quot;10. Figma - 维基百科&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Figma" target="_blank" rel="noreferrer">Figma - Wikipedia</a></p><p><strong>一句话摘要</strong>: Figma是一款向量图形编辑器和白板工具。</p><p><strong>能解决什么问题</strong>: 解决设计师协作和原型创建的问题。</p><p><strong>产品应用</strong>: 可以应用于产品设计、UI/UX设计等领域。</p><p><strong>示例场景</strong>: 设计师使用Figma进行界面设计和协作。</p><hr>',75)])])}const m=r(n,[["render",i]]);export{c as __pageData,m as default};
